function* naturals() {
  let n = 1;
  while (true) {
    yield n;
    n += 1;
  }
}

function take(gen, count) {
  const result = [];
  for (let i = 0; i < count; i++) {
    result.push(gen.next().value);
  }
  return result;
}

console.log(take(naturals(), 5));

